export const MATH_NAV_CSS = ":root {\n    --eq-bg: #f8fafc;\n    --eq-border: #e2e8f0;\n    --eq-text: #0f172a;\n    --eq-highlight: #f59e0b;\n    --eq-highlight-bg: rgba(245, 158, 11, 0.16);\n    --eq-focus: #0284c7;\n    --eq-drawer-bg: #f1f5f9;\n    --eq-card-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);\n    --eq-btn-bg: #ffffff;\n    --eq-btn-border: #cbd5e1;\n    --eq-btn-text: #1e293b;\n    --eq-btn-active-bg: #0284c7;\n    --eq-btn-active-text: #ffffff;\n    --eq-badge-bg: rgba(2, 132, 199, 0.12);\n    --eq-badge-text: #0284c7;\n    --eq-badge-border: rgba(2, 132, 199, 0.3);\n}\n\n@media (prefers-color-scheme: dark) {\n    :root {\n        --eq-bg: rgba(30, 41, 59, 0.7);\n        --eq-border: rgba(255, 255, 255, 0.1);\n        --eq-text: #f8fafc;\n        --eq-drawer-bg: rgba(15, 23, 42, 0.85);\n        --eq-card-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);\n        --eq-btn-bg: rgba(255, 255, 255, 0.08);\n        --eq-btn-border: rgba(255, 255, 255, 0.14);\n        --eq-btn-text: #f8fafc;\n        --eq-badge-bg: rgba(56, 189, 248, 0.14);\n        --eq-badge-text: #38bdf8;\n        --eq-badge-border: rgba(56, 189, 248, 0.35);\n    }\n}\n\n/* SOTA Premium Interactive Equation Styling */\n.interactive-equation-wrapper {\n    position: relative;\n    background-color: var(--eq-bg);\n    border: 1px solid var(--eq-border);\n    color: var(--eq-text);\n    border-radius: 16px;\n    padding: 24px;\n    transition: all 0.25s ease;\n    cursor: pointer;\n    outline: none;\n    box-shadow: var(--eq-card-shadow);\n}\n\n.interactive-equation-wrapper:focus, .interactive-equation-wrapper:focus-within {\n    border-color: var(--eq-focus);\n    box-shadow: 0 0 0 2px rgba(2, 132, 199, 0.3);\n}\n\n.equation-container {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    font-size: 1.4rem;\n    padding: 0.5rem;\n    overflow-x: auto;\n}\n\n.equation-container math {\n    cursor: pointer;\n}\n\n.equation-container math mi:hover,\n.equation-container math mn:hover,\n.equation-container math mo:hover,\n.equation-container math mtext:hover {\n    background-color: rgba(254, 240, 138, 0.45);\n    border-radius: 3px;\n}\n\n/* Active Navigation Visual Highlight styling with vibrant color and zoom-in scale */\n.math-nav-focused {\n    display: inline-block !important;\n    background-color: #fef08a !important; /* High-visibility vibrant yellow/gold highlighter */\n    color: #854d0e !important; /* Deep contrasting amber text */\n    outline: 3px solid #f59e0b !important;\n    outline-offset: 2px !important;\n    border-radius: 4px !important;\n    box-shadow: 0 0 16px rgba(245, 158, 11, 0.75), 0 2px 8px rgba(0, 0, 0, 0.18) !important;\n    font-size: 1.22em !important; /* Scales MathML elements reliably across Chromium, Firefox & WebKit */\n    font-weight: 800 !important;\n    zoom: 1.15 !important;\n    transform: scale(1.15) !important;\n    transform-origin: center !important;\n    transition: transform 0.15s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.15s ease, outline 0.15s ease !important;\n    position: relative !important;\n    z-index: 50 !important;\n    padding: 2px 4px !important;\n}\n.math-nav-focused, .math-nav-focused * {\n    color: #854d0e !important;\n    text-shadow: 0 0 1px rgba(245, 158, 11, 0.4) !important;\n}\n@media (prefers-color-scheme: dark) {\n    .math-nav-focused {\n        background-color: rgba(56, 189, 248, 0.45) !important;\n        outline: 3px solid #38bdf8 !important;\n        box-shadow: 0 0 20px rgba(56, 189, 248, 0.8), 0 2px 8px rgba(0, 0, 0, 0.4) !important;\n        color: #f8fafc !important;\n    }\n    .math-nav-focused, .math-nav-focused * {\n        color: #f8fafc !important;\n        text-shadow: 0 0 2px rgba(56, 189, 248, 0.8) !important;\n    }\n}\n\n/* SRE SOTA Drawer styling */\n.in-place-nav-drawer {\n    width: 100%;\n    margin-top: 16px;\n    padding: 16px;\n    background: var(--eq-drawer-bg);\n    border: 1px dashed var(--eq-border);\n    border-radius: 12px;\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n    text-align: center;\n    animation: fadeInDrawer 0.25s ease-out;\n}\n\n@keyframes fadeInDrawer {\n    from { opacity: 0; transform: translateY(-6px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n.in-place-nav-header {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 6px;\n}\n\n.in-place-level-badge {\n    font-size: 0.75rem;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    color: var(--eq-badge-text);\n    background: var(--eq-badge-bg);\n    padding: 4px 12px;\n    border-radius: 9999px;\n    border: 1px solid var(--eq-badge-border);\n}\n\n.in-place-speech-text {\n    font-size: 0.95rem;\n    font-style: italic;\n    opacity: 0.85;\n}\n\n.in-place-term-list {\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: center;\n    align-items: center;\n    gap: 8px;\n    padding: 10px;\n    background: rgba(0, 0, 0, 0.05);\n    border-radius: 10px;\n    max-width: 100%;\n    overflow-x: auto;\n}\n\n.in-place-term-btn {\n    min-height: 44px;\n    min-width: 44px;\n    background: var(--eq-btn-bg);\n    border: 1px solid var(--eq-btn-border);\n    color: var(--eq-btn-text);\n    padding: 8px 16px;\n    border-radius: 8px;\n    cursor: pointer;\n    font-size: 1.15rem;\n    font-weight: 600;\n    outline: none;\n    transition: all 0.2s ease;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.in-place-term-btn:hover, .in-place-term-btn:focus-visible, .in-place-term-btn.active {\n    border-color: var(--eq-focus);\n    background: var(--eq-btn-active-bg);\n    color: var(--eq-btn-active-text);\n    box-shadow: 0 0 14px rgba(2, 132, 199, 0.35);\n    transform: translateY(-2px) scale(1.03);\n}\n\n.in-place-shortcuts {\n    display: flex;\n    justify-content: center;\n    gap: 12px;\n    flex-wrap: wrap;\n    font-size: 0.78rem;\n    opacity: 0.8;\n}\n\n.in-place-shortcuts kbd {\n    background: var(--eq-btn-bg);\n    border: 1px solid var(--eq-btn-border);\n    border-radius: 4px;\n    padding: 2px 6px;\n    font-size: 0.75rem;\n    color: var(--eq-text);\n}\n\n.eq-actions-overlay {\n    display: flex;\n    justify-content: center;\n    gap: 10px;\n    margin-top: 14px;\n    flex-wrap: wrap;\n}\n\n.eq-action-btn {\n    min-height: 44px;\n    background: var(--eq-btn-bg);\n    border: 1px solid var(--eq-btn-border);\n    color: var(--eq-btn-text);\n    padding: 8px 14px;\n    border-radius: 8px;\n    cursor: pointer;\n    font-size: 0.88rem;\n    font-weight: 600;\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    transition: all 0.2s ease;\n}\n\n.eq-action-btn:hover, .eq-action-btn:focus-visible {\n    border-color: var(--eq-focus);\n    background: var(--eq-highlight-bg);\n    color: var(--eq-text);\n}\n\n/* Built-in Code & Details Modal Overlay */\n.math-details-modal-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background: rgba(0, 0, 0, 0.65);\n    backdrop-filter: blur(4px);\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    z-index: 99999;\n    padding: 16px;\n    animation: fadeInModal 0.2s ease-out;\n}\n\n@keyframes fadeInModal {\n    from { opacity: 0; }\n    to { opacity: 1; }\n}\n\n.math-details-modal {\n    background: var(--eq-bg);\n    color: var(--eq-text);\n    border: 1px solid var(--eq-border);\n    border-radius: 16px;\n    width: 100%;\n    max-width: 640px;\n    max-height: 85vh;\n    display: flex;\n    flex-direction: column;\n    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3);\n    overflow: hidden;\n}\n\n.math-modal-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 16px 20px;\n    border-bottom: 1px solid var(--eq-border);\n}\n\n.math-modal-header h2 {\n    font-size: 1.15rem;\n    margin: 0;\n}\n\n.math-modal-close-btn {\n    background: none;\n    border: none;\n    font-size: 1.5rem;\n    color: var(--eq-text);\n    cursor: pointer;\n    line-height: 1;\n    min-width: 44px;\n    min-height: 44px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    border-radius: 8px;\n}\n\n.math-modal-body {\n    padding: 20px;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n}\n\n.math-modal-section {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n\n.math-modal-sec-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.math-modal-section label {\n    font-size: 0.85rem;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    opacity: 0.8;\n}\n\n.math-modal-speech {\n    margin: 0;\n    padding: 10px 14px;\n    background: var(--eq-drawer-bg);\n    border-radius: 8px;\n    font-size: 0.95rem;\n}\n\n.math-modal-section pre {\n    margin: 0;\n    padding: 12px;\n    background: var(--eq-drawer-bg);\n    border-radius: 8px;\n    overflow-x: auto;\n    font-size: 0.85rem;\n    border: 1px solid var(--eq-border);\n}\n\n.math-copy-btn {\n    background: var(--eq-btn-bg);\n    border: 1px solid var(--eq-btn-border);\n    color: var(--eq-btn-text);\n    padding: 4px 10px;\n    border-radius: 6px;\n    font-size: 0.78rem;\n    font-weight: 600;\n    cursor: pointer;\n    min-height: 32px;\n    transition: all 0.2s ease;\n}\n\n.math-copy-btn:hover {\n    border-color: var(--eq-focus);\n    background: var(--eq-badge-bg);\n}\n\n/* Equalify Iris Modern Accessible Document Theme */\n:root {\n  --bg-color: #0f172a;\n  --card-bg: #1e293b;\n  --card-border: #334155;\n  --text-main: #f8fafc;\n  --text-muted: #94a3b8;\n  --accent: #38bdf8;\n  --accent-hover: #0ea5e9;\n  --accent-subtle: rgba(56, 189, 248, 0.12);\n  --border-color: #334155;\n  --code-bg: #0b1120;\n  --focus-ring: #38bdf8;\n}\n\n@media (prefers-color-scheme: light) {\n  :root {\n    --bg-color: #ffffff;\n    --card-bg: #f8fafc;\n    --card-border: #e2e8f0;\n    --text-main: #0f172a;\n    --text-muted: #475569;\n    --accent: #0284c7;\n    --accent-hover: #0369a1;\n    --accent-subtle: rgba(2, 132, 199, 0.08);\n    --border-color: #e2e8f0;\n    --code-bg: #f1f5f9;\n    --focus-ring: #0284c7;\n  }\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;\n  line-height: 1.68;\n  background-color: var(--bg-color);\n  color: var(--text-main);\n  max-width: 1040px;\n  margin: 0 auto;\n  padding: 2.5rem 1.5rem;\n  text-rendering: optimizeLegibility;\n}\n\nheader {\n  margin-bottom: 2.5rem;\n  border-bottom: 2px solid var(--border-color);\n  padding-bottom: 1.5rem;\n}\n\nh1, h2, h3, h4, h5, h6 {\n  color: var(--text-main);\n  line-height: 1.25;\n  font-weight: 700;\n  margin-top: 1.75rem;\n  margin-bottom: 0.75rem;\n}\n\nh1 { font-size: 2.1rem; }\nh2 { font-size: 1.55rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.4rem; }\nh3 { font-size: 1.25rem; }\n\np, li, dd {\n  font-size: 1.02rem;\n  color: var(--text-main);\n}\n\n.document-badge {\n  display: inline-block;\n  font-size: 0.8rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 1.2px;\n  color: var(--accent);\n  background: var(--accent-subtle);\n  padding: 4px 12px;\n  border-radius: 9999px;\n  border: 1px solid var(--border-color);\n  margin-bottom: 0.75rem;\n}\n\n/* Accessible Interactive Equation Card */\n.interactive-equation-wrapper {\n  background-color: var(--card-bg) !important;\n  border: 1px solid var(--card-border) !important;\n  border-radius: 8px !important;\n  margin: 1.5rem 0 !important;\n  padding: 1.25rem !important;\n  position: relative !important;\n  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05) !important;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease !important;\n}\n\n.interactive-equation-wrapper:focus,\n.interactive-equation-wrapper:focus-within {\n  outline: 3px solid var(--focus-ring) !important;\n  outline-offset: 2px !important;\n}\n\n.equation-container {\n  display: flex !important;\n  justify-content: center !important;\n  align-items: center !important;\n  overflow-x: auto !important;\n  padding: 0.75rem 0.5rem !important;\n}\n\n/* In-Place Sub-Expression Navigation Drawer */\n.in-place-nav-drawer {\n  background: var(--code-bg) !important;\n  border: 1px dashed var(--border-color) !important;\n  border-radius: 6px !important;\n  padding: 1rem !important;\n  margin-top: 0.75rem !important;\n}\n\n.in-place-term-btn {\n  background: var(--card-bg) !important;\n  border: 1px solid var(--border-color) !important;\n  color: var(--text-main) !important;\n  border-radius: 4px !important;\n  padding: 4px 10px !important;\n  margin: 3px !important;\n  font-size: 0.92rem !important;\n  cursor: pointer !important;\n}\n\n.in-place-term-btn:focus,\n.in-place-term-btn.active {\n  outline: 2px solid var(--accent) !important;\n  background: var(--accent-subtle) !important;\n}\n\n.eq-actions-overlay {\n  display: flex !important;\n  gap: 0.5rem !important;\n  justify-content: flex-end !important;\n  margin-top: 0.5rem !important;\n}\n\n.eq-action-btn {\n  background: var(--card-bg) !important;\n  border: 1px solid var(--border-color) !important;\n  color: var(--text-muted) !important;\n  border-radius: 4px !important;\n  padding: 4px 10px !important;\n  font-size: 0.85rem !important;\n  cursor: pointer !important;\n  transition: color 0.15s, border-color 0.15s !important;\n}\n\n.eq-action-btn:hover,\n.eq-action-btn:focus {\n  color: var(--accent) !important;\n  border-color: var(--accent) !important;\n  outline: none !important;\n}\n\n/* Inline Math Styling */\n.inline-math-wrapper {\n  display: inline-block;\n  padding: 1px 4px;\n  background: var(--accent-subtle);\n  border-radius: 3px;\n  border: 1px solid transparent;\n  vertical-align: middle;\n}\n\n.inline-math-wrapper:focus {\n  outline: 2px solid var(--focus-ring);\n  border-color: var(--accent);\n}\n\n/* Accessible Table Styles */\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 1.5rem 0;\n}\n\nth, td {\n  border: 1px solid var(--border-color);\n  padding: 0.75rem 1rem;\n  text-align: left;\n}\n\nth {\n  background-color: var(--card-bg);\n  font-weight: 600;\n}\n\n/* Page Break Indication */\nhr[role=\"doc-pagebreak\"] {\n  border: none;\n  border-top: 2px dashed var(--border-color);\n  margin: 2.5rem 0;\n  position: relative;\n}\n\nhr[role=\"doc-pagebreak\"]::after {\n  content: attr(aria-label);\n  position: absolute;\n  top: -12px;\n  right: 10px;\n  background: var(--card-bg);\n  padding: 0 8px;\n  font-size: 0.8rem;\n  color: var(--text-muted);\n}\n\nfooter {\n  margin-top: 4rem;\n  padding-top: 2rem;\n  border-top: 1px solid var(--border-color);\n  font-size: 0.9rem;\n  color: var(--text-muted);\n  text-align: center;\n}";

export const MATH_NAV_SCRIPT = "document.addEventListener('DOMContentLoaded', () => {\n    // Shared Toast Live Region for Screen Reader Feedback\n    let toastContainer = document.getElementById('sr-toast-container');\n    if (!toastContainer) {\n        toastContainer = document.createElement('div');\n        toastContainer.id = 'sr-toast-container';\n        toastContainer.setAttribute('role', 'status');\n        toastContainer.setAttribute('aria-live', 'polite');\n        toastContainer.style.cssText = 'position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden;';\n        document.body.appendChild(toastContainer);\n    }\n    \n    function showToast(msg) {\n        if (toastContainer) {\n            toastContainer.textContent = '';\n            setTimeout(() => { toastContainer.textContent = msg; }, 50);\n        }\n    }\n\n    let activeInPlaceWrapper = null;\n    let activeInPlaceNavTree = null;\n    let activeInPlaceNavNode = null;\n\n    function updateVisualHighlight(wrapper, activeNode) {\n        const mathEl = wrapper.querySelector('.equation-container math');\n        if (!mathEl) return;\n        \n        // Remove highlight from all elements inside this math element\n        const highlighted = mathEl.querySelectorAll('.math-nav-focused');\n        highlighted.forEach(el => {\n            el.classList.remove('math-nav-focused');\n        });\n        \n        // Collect targeted visible leaf tokens to highlight\n        const targetElements = new Set();\n        if (activeNode && activeNode.domElements) {\n            activeNode.domElements.forEach(el => {\n                if (el && typeof el.classList === 'object') {\n                    const tag = el.tagName ? el.tagName.toLowerCase() : '';\n                    if (['mi', 'mn', 'mo', 'mtext'].includes(tag)) {\n                        targetElements.add(el);\n                    } else {\n                        const leaves = el.querySelectorAll('mi, mn, mo, mtext');\n                        if (leaves.length > 0) {\n                            leaves.forEach(leaf => targetElements.add(leaf));\n                        } else {\n                            targetElements.add(el);\n                        }\n                    }\n                }\n            });\n        }\n\n        // Apply highlight and zoom to targeted tokens\n        targetElements.forEach(el => {\n            el.classList.add('math-nav-focused');\n        });\n    }\n\n    function findNavNodeForElement(rootNode, targetEl) {\n        if (!rootNode || !targetEl) return null;\n        let bestMatch = null;\n        let maxDepth = -1;\n\n        function search(node) {\n            if (!node) return;\n            let containsTarget = false;\n            if (node.domElements && Array.isArray(node.domElements)) {\n                containsTarget = node.domElements.some(el => {\n                    return el === targetEl || (el.contains && el.contains(targetEl));\n                });\n            }\n            if (containsTarget) {\n                if (node.depth >= maxDepth) {\n                    maxDepth = node.depth;\n                    bestMatch = node;\n                }\n                if (node.children && node.children.length > 0) {\n                    for (let child of node.children) {\n                        search(child);\n                    }\n                }\n            }\n        }\n\n        search(rootNode);\n        return bestMatch;\n    }\n\n    function clearVisualHighlight(wrapper) {\n        const mathEl = wrapper.querySelector('.equation-container math');\n        if (!mathEl) return;\n        const highlighted = mathEl.querySelectorAll('.math-nav-focused');\n        highlighted.forEach(el => {\n            el.classList.remove('math-nav-focused');\n        });\n    }\n\n    function initInPlaceNavTree(wrapper) {\n        const rootMathEl = wrapper.querySelector('.equation-container math');\n        if (!rootMathEl) return null;\n        const speech = wrapper.getAttribute('data-speech') || 'Mathematical formula';\n        try {\n            function cleanWhitespace(node) {\n                for (let i = node.childNodes.length - 1; i >= 0; i--) {\n                    const child = node.childNodes[i];\n                    if (child.nodeType === 3 && !child.textContent.trim()) {\n                        node.removeChild(child);\n                    } else if (child.nodeType === 1) {\n                        cleanWhitespace(child);\n                    }\n                }\n            }\n            cleanWhitespace(rootMathEl);\n            \n            const rootGroup = { type: 'single', element: rootMathEl };\n            const navTree = buildNavNode(rootGroup);\n            if (!navTree.speech || navTree.speech === \"\") {\n                navTree.speech = speech;\n            }\n            return navTree;\n        } catch (err) {\n            console.error(\"Error parsing in-place math navigation tree:\", err);\n            return null;\n        }\n    }\n\n    function renderInPlaceDrawer(wrapper, node, shouldFocus = true) {\n        const drawer = wrapper.querySelector('.in-place-nav-drawer');\n        if (!drawer) return;\n\n        // Visual Highlight update\n        updateVisualHighlight(wrapper, node);\n\n        const levelBadge = drawer.querySelector('.in-place-level-badge');\n        const speechText = drawer.querySelector('.in-place-speech-text');\n        const termList = drawer.querySelector('.in-place-term-list');\n\n        if (levelBadge) {\n            if (node.levelName && (node.levelName.includes('Fraction') || node.levelName.includes('Numerator') || node.levelName.includes('Denominator') || node.levelName.includes('Root') || node.levelName.includes('Matrix') || node.levelName.includes('Row') || node.levelName.includes('Cell'))) {\n                levelBadge.textContent = node.levelName;\n                levelBadge.style.display = 'inline-block';\n            } else {\n                levelBadge.style.display = 'none';\n            }\n        }\n\n        if (speechText) {\n            speechText.textContent = node.navSpeech || node.speech || node.text || '';\n        }\n\n        if (termList) {\n            const siblings = (node.parent) ? node.parent.children : [node];\n            const currentParent = wrapper._activeParentNode || null;\n            const parentChanged = (node.parent !== currentParent || termList.children.length === 0);\n\n            if (parentChanged) {\n                wrapper._activeParentNode = node.parent;\n                termList.innerHTML = '';\n                siblings.forEach((sNode, idx) => {\n                    const btn = document.createElement('button');\n                    btn.type = 'button';\n                    btn.className = 'in-place-term-btn';\n                    \n                    const speechStr = sNode.navSpeech || sNode.speech || sNode.text || 'Term';\n                    btn.setAttribute('aria-label', speechStr);\n                    btn.innerHTML = `<span aria-hidden=\"true\">${sNode.html || sNode.text}</span>`;\n\n                    btn.addEventListener('click', (e) => {\n                        e.preventDefault();\n                        e.stopPropagation();\n                        if (activeInPlaceNavNode === sNode) {\n                            if (sNode.children && sNode.children.length > 0) {\n                                activeInPlaceNavNode = sNode.children[0];\n                                renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                            }\n                        } else {\n                            activeInPlaceNavNode = sNode;\n                            renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                        }\n                    });\n\n                    btn.addEventListener('focus', (e) => {\n                        if (activeInPlaceNavNode !== sNode) {\n                            activeInPlaceNavNode = sNode;\n                            renderInPlaceDrawer(wrapper, activeInPlaceNavNode, false);\n                        }\n                    });\n\n                    btn.addEventListener('keydown', (e) => {\n                        let curSiblings = (activeInPlaceNavNode.parent) ? activeInPlaceNavNode.parent.children : [activeInPlaceNavNode];\n                        let curIdx = curSiblings.indexOf(activeInPlaceNavNode);\n                        const key = e.key;\n\n                        // Global Exit keys: Backspace, Q, X\n                        if (key === 'Backspace' || key === 'q' || key === 'Q' || key === 'x' || key === 'X') {\n                            e.preventDefault();\n                            e.stopPropagation();\n                            closeInPlaceDrawer(wrapper);\n                            return;\n                        }\n\n                        switch (key) {\n                            case 'ArrowLeft':\n                                e.preventDefault();\n                                e.stopPropagation();\n                                if (curIdx > 0) {\n                                    activeInPlaceNavNode = curSiblings[curIdx - 1];\n                                    renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                                } else {\n                                    showToast(\"Start of part\");\n                                }\n                                break;\n                            case 'ArrowRight':\n                                e.preventDefault();\n                                e.stopPropagation();\n                                if (curIdx < curSiblings.length - 1) {\n                                    activeInPlaceNavNode = curSiblings[curIdx + 1];\n                                    renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                                } else {\n                                    showToast(\"End of part\");\n                                }\n                                break;\n                            case 'ArrowUp':\n                            case 'Escape':\n                                e.preventDefault();\n                                e.stopPropagation();\n                                if (activeInPlaceNavNode.parent) {\n                                    activeInPlaceNavNode = activeInPlaceNavNode.parent;\n                                    renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                                } else {\n                                    closeInPlaceDrawer(wrapper);\n                                }\n                                break;\n                            case 'ArrowDown':\n                            case 'Enter':\n                            case ' ':\n                                e.preventDefault();\n                                e.stopPropagation();\n                                if (activeInPlaceNavNode.children && activeInPlaceNavNode.children.length > 0) {\n                                    activeInPlaceNavNode = activeInPlaceNavNode.children[0];\n                                    renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                                } else {\n                                    showToast(\"Reached lowest level term\");\n                                }\n                                break;\n                        }\n                    });\n\n                    termList.appendChild(btn);\n                });\n            }\n\n            // Sync active state visually\n            const buttons = termList.querySelectorAll('.in-place-term-btn');\n            let activeBtn = null;\n            buttons.forEach((btn, idx) => {\n                const sNode = siblings[idx];\n                if (sNode === node) {\n                    btn.classList.add('active');\n                    activeBtn = btn;\n                } else {\n                    btn.classList.remove('active');\n                }\n            });\n\n            if (activeBtn && shouldFocus) {\n                activeBtn.focus();\n            }\n        }\n    }\n\n    function closeInPlaceDrawer(wrapper) {\n        if (!wrapper) return;\n        const drawer = wrapper.querySelector('.in-place-nav-drawer');\n        if (drawer) {\n            drawer.style.display = 'none';\n            drawer.setAttribute('aria-hidden', 'true');\n        }\n        \n        // Clear visual highlights\n        clearVisualHighlight(wrapper);\n\n        wrapper._activeParentNode = null;\n        activeInPlaceWrapper = null;\n        activeInPlaceNavTree = null;\n        activeInPlaceNavNode = null;\n        wrapper.focus();\n    }\n\n    function showEquationDetailsModal(wrapper) {\n        const desc = wrapper.getAttribute('data-description') || 'Mathematical Equation';\n        const speech = wrapper.getAttribute('data-speech') || '';\n        const speechEs = wrapper.getAttribute('data-speech-es') || '';\n        const mathml = wrapper.getAttribute('data-mathml') || '';\n        const latex = wrapper.getAttribute('data-latex') || '';\n        const braille = wrapper.getAttribute('data-braille') || '';\n\n        // Create modal overlay\n        const overlay = document.createElement('div');\n        overlay.className = 'math-details-modal-overlay';\n        overlay.setAttribute('role', 'dialog');\n        overlay.setAttribute('aria-modal', 'true');\n        overlay.setAttribute('aria-label', 'Equation Code & Details');\n\n        let speechEsHtml = '';\n        if (speechEs) {\n            speechEsHtml = `\n            <div class=\"math-modal-section\">\n                <label>Lectura en Espa\u00f1ol (Spanish Reading)</label>\n                <p class=\"math-modal-speech\">${escapeHtml(speechEs)}</p>\n            </div>`;\n        }\n\n        let latexHtml = '';\n        if (latex) {\n            latexHtml = `\n            <div class=\"math-modal-section\">\n                <div class=\"math-modal-sec-header\">\n                    <label>LaTeX Source</label>\n                    <button type=\"button\" class=\"math-copy-btn\" id=\"copy-latex-btn\">Copy LaTeX</button>\n                </div>\n                <pre><code>${escapeHtml(latex)}</code></pre>\n            </div>`;\n        }\n\n        let brailleHtml = '';\n        if (braille) {\n            brailleHtml = `\n            <div class=\"math-modal-section\">\n                <div class=\"math-modal-sec-header\">\n                    <label>Braille Code (Nemeth / UEB)</label>\n                    <button type=\"button\" class=\"math-copy-btn\" id=\"copy-braille-btn\">Copy Braille</button>\n                </div>\n                <pre><code>${escapeHtml(braille)}</code></pre>\n            </div>`;\n        }\n\n        overlay.innerHTML = `\n        <div class=\"math-details-modal\">\n            <div class=\"math-modal-header\">\n                <h2>${escapeHtml(desc)}</h2>\n                <button type=\"button\" class=\"math-modal-close-btn\" aria-label=\"Close details dialog\">&times;</button>\n            </div>\n            <div class=\"math-modal-body\">\n                <div class=\"math-modal-section\">\n                    <label>Spoken Reading (English)</label>\n                    <p class=\"math-modal-speech\">${escapeHtml(speech)}</p>\n                </div>\n                ${speechEsHtml}\n                ${latexHtml}\n                <div class=\"math-modal-section\">\n                    <div class=\"math-modal-sec-header\">\n                        <label>MathML 3.0 Source</label>\n                        <button type=\"button\" class=\"math-copy-btn\" id=\"copy-mathml-btn\">Copy MathML</button>\n                    </div>\n                    <pre><code>${escapeHtml(mathml)}</code></pre>\n                </div>\n                ${brailleHtml}\n            </div>\n        </div>`;\n\n        document.body.appendChild(overlay);\n\n        function closeModal() {\n            if (overlay && overlay.parentNode) {\n                overlay.parentNode.removeChild(overlay);\n            }\n            wrapper.focus();\n        }\n\n        const closeBtn = overlay.querySelector('.math-modal-close-btn');\n        closeBtn.addEventListener('click', closeModal);\n\n        overlay.addEventListener('click', (e) => {\n            if (e.target === overlay) closeModal();\n        });\n\n        overlay.addEventListener('keydown', (e) => {\n            if (e.key === 'Escape') {\n                e.preventDefault();\n                closeModal();\n            }\n        });\n\n        // Copy buttons\n        function setupCopy(btnId, textToCopy, labelText) {\n            const btn = overlay.querySelector('#' + btnId);\n            if (!btn) return;\n            btn.addEventListener('click', () => {\n                navigator.clipboard.writeText(textToCopy).then(() => {\n                    const orig = btn.textContent;\n                    btn.textContent = 'Copied!';\n                    setTimeout(() => { btn.textContent = orig; }, 1800);\n                });\n            });\n        }\n\n        if (latex) setupCopy('copy-latex-btn', latex, 'LaTeX');\n        if (mathml) setupCopy('copy-mathml-btn', mathml, 'MathML');\n        if (braille) setupCopy('copy-braille-btn', braille, 'Braille');\n\n        closeBtn.focus();\n    }\n\n    function escapeHtml(str) {\n        return (str || '').replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\").replace(/'/g, \"&#039;\");\n    }\n\n    // Equation click & keyboard triggers\n    const eqWrappers = document.querySelectorAll('.interactive-equation-wrapper, .inline-math-wrapper');\n    eqWrappers.forEach(wrapper => {\n        wrapper.addEventListener('click', (e) => {\n            if (e.target.closest('.speak-btn')) {\n                e.preventDefault();\n                e.stopPropagation();\n                const btn = e.target.closest('.speak-btn');\n                const lang = btn.getAttribute('data-lang') || 'en';\n                const speech = (lang === 'es')\n                    ? (wrapper.getAttribute('data-speech-es') || wrapper.getAttribute('data-speech') || '')\n                    : (wrapper.getAttribute('data-speech') || '');\n                if ('speechSynthesis' in window) {\n                    window.speechSynthesis.cancel();\n                    const u = new SpeechSynthesisUtterance(speech);\n                    u.rate = 0.9;\n                    u.lang = (lang === 'es') ? 'es-ES' : 'en-US';\n                    const voices = window.speechSynthesis.getVoices();\n                    const matchedVoice = voices.find(v => v.lang && v.lang.toLowerCase().startsWith(lang));\n                    if (matchedVoice) {\n                        u.voice = matchedVoice;\n                    }\n                    window.speechSynthesis.speak(u);\n                }\n                return;\n            }\n            if (e.target.closest('.focus-btn')) {\n                // Focus details handler if present in host page, else built-in fallback\n                if (typeof openEquationDetails === 'function') {\n                    openEquationDetails(wrapper);\n                } else {\n                    showEquationDetailsModal(wrapper);\n                }\n                e.stopPropagation();\n                return;\n            }\n            if (e.target.closest('.in-place-nav-drawer')) {\n                // Click was inside the navigation drawer, keep open\n                return;\n            }\n            if (e.target.closest('.nav-toggle-btn')) {\n                if (activeInPlaceWrapper === wrapper) {\n                    closeInPlaceDrawer(wrapper);\n                } else {\n                    startInPlaceNav(wrapper);\n                }\n                return;\n            }\n            // Direct click on a specific math token inside the equation\n            const clickedMathToken = e.target.closest('.equation-container math mi, .equation-container math mn, .equation-container math mo, .equation-container math mtext');\n            if (clickedMathToken) {\n                if (activeInPlaceWrapper !== wrapper) {\n                    startInPlaceNav(wrapper);\n                }\n                if (activeInPlaceNavTree) {\n                    const matchedNode = findNavNodeForElement(activeInPlaceNavTree, clickedMathToken);\n                    if (matchedNode) {\n                        activeInPlaceNavNode = matchedNode;\n                        renderInPlaceDrawer(wrapper, activeInPlaceNavNode, true);\n                    }\n                }\n                return;\n            }\n            if (e.target.closest('.equation-container') || wrapper.classList.contains('interactive-equation-wrapper')) {\n                if (activeInPlaceWrapper !== wrapper) {\n                    startInPlaceNav(wrapper);\n                }\n            }\n        });\n\n        wrapper.addEventListener('keydown', (e) => {\n            if (!activeInPlaceWrapper) {\n                if (e.key === 'Enter' || e.key === 'ArrowDown') {\n                    startInPlaceNav(wrapper);\n                    e.preventDefault();\n                } else if (e.key === ' ' || e.key === 's' || e.key === 'S') {\n                    const speech = wrapper.getAttribute('data-speech') || '';\n                    if ('speechSynthesis' in window) {\n                        window.speechSynthesis.cancel();\n                        const u = new SpeechSynthesisUtterance(speech);\n                        u.rate = 0.9;\n                        window.speechSynthesis.speak(u);\n                    }\n                    e.preventDefault();\n                }\n            }\n        });\n    });\n\n    function startInPlaceNav(wrapper) {\n        if (activeInPlaceWrapper && activeInPlaceWrapper !== wrapper) {\n            closeInPlaceDrawer(activeInPlaceWrapper);\n        }\n        activeInPlaceWrapper = wrapper;\n        const drawer = wrapper.querySelector('.in-place-nav-drawer');\n        if (drawer) {\n            drawer.style.display = 'flex';\n            drawer.setAttribute('aria-hidden', 'false');\n        }\n        activeInPlaceNavTree = initInPlaceNavTree(wrapper);\n        if (activeInPlaceNavTree) {\n            if (activeInPlaceNavTree.children && activeInPlaceNavTree.children.length > 0) {\n                activeInPlaceNavNode = activeInPlaceNavTree.children[0];\n            } else {\n                activeInPlaceNavNode = activeInPlaceNavTree;\n            }\n            renderInPlaceDrawer(wrapper, activeInPlaceNavNode);\n        }\n    }\n\n    // Parentheses grouping\n    function groupChildElements(elements) {\n        const groups = [];\n        let i = 0;\n        while (i < elements.length) {\n            const el = elements[i];\n            const text = el.textContent.trim();\n            if (el.tagName.toLowerCase() === 'mo' && (text === '(' || text === '[' || text === '{')) {\n                let openCount = 1;\n                let j = i + 1;\n                while (j < elements.length && openCount > 0) {\n                    const nextEl = elements[j];\n                    const nextText = nextEl.textContent.trim();\n                    if (nextEl.tagName.toLowerCase() === 'mo') {\n                        if (nextText === '(' || nextText === '[' || nextText === '{') {\n                            openCount++;\n                        } else if (nextText === ')' || nextText === ']' || nextText === '}') {\n                            openCount--;\n                        }\n                    }\n                    if (openCount === 0) break;\n                    j++;\n                }\n                if (j < elements.length && openCount === 0) {\n                    const subElements = elements.slice(i, j + 1);\n                    groups.push({\n                        type: 'fence',\n                        elements: subElements\n                    });\n                    i = j + 1;\n                } else {\n                    groups.push({\n                        type: 'single',\n                        element: el\n                    });\n                    i++;\n                }\n            } else {\n                groups.push({\n                    type: 'single',\n                    element: el\n                });\n                i++;\n            }\n        }\n        return groups;\n    }\n\n    // Semantic grouping with complete operator tiers\n    function semanticGroup(groupsList) {\n        if (groupsList.length <= 1) {\n            return groupsList[0] || { type: 'single', element: document.createElement('mrow') };\n        }\n\n        function isOp(g, ops) {\n            if (g.type !== 'single') return false;\n            const el = g.element;\n            if (!el || el.tagName.toLowerCase() !== 'mo') return false;\n            return ops.includes(el.textContent.trim());\n        }\n\n        // Tier 1: Relations\n        const relOps = ['=', '\u2260', '<', '>', '\u2264', '\u2265', '\u2248', '\u2261', '\u221d', '\u2208', '\u2209', '\u2282', '\u2286', '\u21d2', '\u21d4', '\u2192', '\u21c4', '\u21cc'];\n        let relParts = [];\n        let currentPart = [];\n        for (let g of groupsList) {\n            if (isOp(g, relOps)) {\n                if (currentPart.length > 0) {\n                    relParts.push({ type: 'expr_group', elements: currentPart });\n                    currentPart = [];\n                }\n                relParts.push({ type: 'operator', group: g });\n            } else {\n                currentPart.push(g);\n            }\n        }\n        if (currentPart.length > 0) {\n            relParts.push({ type: 'expr_group', elements: currentPart });\n        }\n\n        if (relParts.length > 1) {\n            return {\n                type: 'relation',\n                children: relParts.map(part => {\n                    if (part.type === 'operator') {\n                        return part.group;\n                    } else {\n                        return semanticGroup(part.elements);\n                    }\n                })\n            };\n        }\n\n        // Tier 2: Additive & Set Unions\n        const addOps = ['+', '-', '\u2212', '\u00b1', '\u2213', '\u2295', '\u222a'];\n        let addParts = [];\n        currentPart = [];\n        for (let g of groupsList) {\n            if (isOp(g, addOps)) {\n                if (currentPart.length > 0) {\n                    addParts.push({ type: 'term_group', elements: currentPart });\n                    currentPart = [];\n                }\n                addParts.push({ type: 'operator', group: g });\n            } else {\n                currentPart.push(g);\n            }\n        }\n        if (currentPart.length > 0) {\n            addParts.push({ type: 'term_group', elements: currentPart });\n        }\n\n        if (addParts.length > 1) {\n            return {\n                type: 'addition',\n                children: addParts.map(part => {\n                    if (part.type === 'operator') {\n                        return part.group;\n                    } else {\n                        return semanticGroup(part.elements);\n                    }\n                })\n            };\n        }\n\n        // Tier 3: Multiplicative & Set Intersections\n        const multOps = ['*', '\u00b7', '\u22c5', '\u00d7', '/', '\u00f7', '\u2297', '\u2229'];\n        let multParts = [];\n        currentPart = [];\n        for (let g of groupsList) {\n            if (isOp(g, multOps)) {\n                if (currentPart.length > 0) {\n                    multParts.push({ type: 'factor_group', elements: currentPart });\n                    currentPart = [];\n                }\n                multParts.push({ type: 'operator', group: g });\n            } else {\n                currentPart.push(g);\n            }\n        }\n        if (currentPart.length > 0) {\n            multParts.push({ type: 'factor_group', elements: currentPart });\n        }\n\n        if (multParts.length > 1) {\n            return {\n                type: 'multiplication',\n                children: multParts.map(part => {\n                    if (part.type === 'operator') {\n                        return part.group;\n                    } else {\n                        return semanticGroup(part.elements);\n                    }\n                })\n            };\n        }\n\n        if (groupsList.length > 1) {\n            return {\n                type: 'multiplication',\n                children: groupsList\n            };\n        }\n\n        return groupsList[0];\n    }\n\n    // Build navigation node recursively with 2D tables, limits, conjugates\n    function buildSemanticNavNode(semNode, parent = null, depth = 0) {\n        let node = {\n            parent: parent,\n            depth: depth,\n            text: \"\",\n            html: \"\",\n            speech: \"\",\n            navSpeech: \"\",\n            mathmlStr: \"\",\n            children: [],\n            type: \"\",\n            levelName: \"\",\n            domElements: []\n        };\n\n        if (semNode.type === 'multiplication' && semNode.children && semNode.children.length === 2) {\n            const firstChild = semNode.children[0];\n            const secondChild = semNode.children[1];\n            if (firstChild.type === 'single' && secondChild.type === 'fence') {\n                const firstEl = firstChild.element;\n                const firstTag = firstEl.tagName.toLowerCase();\n                if (firstTag === 'mi' || firstTag === 'mo' || firstTag === 'mtext') {\n                    const insideEls = secondChild.elements.slice(1, -1);\n                    const subGroups = groupChildElements(insideEls);\n                    const grouped = semanticGroup(subGroups);\n                    if (grouped.type === 'addition') {\n                        node.type = 'function_of_sum';\n                        const funcName = firstEl.textContent.trim();\n                        const prefixNode = {\n                            parent: node,\n                            depth: depth + 1,\n                            text: funcName + \" of\",\n                            html: `<span class=\"func-prefix\">${funcName} of</span>`,\n                            speech: getElementSpeech(firstEl) + \" of\",\n                            navSpeech: getElementSpeech(firstEl) + \" of\",\n                            mathmlStr: new XMLSerializer().serializeToString(firstEl),\n                            children: [],\n                            type: 'function_prefix',\n                            levelName: \"Level \" + (depth + 1) + \": Function Prefix\",\n                            domElements: [firstEl]\n                        };\n                        const innerAdditionNode = buildSemanticNavNode(grouped, node, depth + 1);\n                        node.children = [prefixNode].concat(innerAdditionNode.children);\n                        node.text = funcName + \"(\" + innerAdditionNode.text + \")\";\n                        node.html = `${funcName}(${innerAdditionNode.html})`;\n                        node.speech = getElementSpeech(firstEl) + \" of \" + innerAdditionNode.speech;\n                        node.mathmlStr = `<mrow>${new XMLSerializer().serializeToString(firstEl)}${secondChild.elements.map(el => new XMLSerializer().serializeToString(el)).join(\"\")}</mrow>`;\n                        node.levelName = \"Level \" + depth + \": Function of Sum\";\n                        node.domElements = [firstEl].concat(secondChild.elements || []);\n                        return node;\n                    }\n                }\n            }\n        }\n\n        if (semNode.type === 'single') {\n            const el = semNode.element;\n            const tagName = el.tagName.toLowerCase();\n            node.text = el.textContent.trim();\n            node.html = el.textContent.trim();\n            node.type = tagName;\n            node.speech = getElementSpeech(el);\n            node.mathmlStr = new XMLSerializer().serializeToString(el);\n            node.domElements = [el];\n\n            if (tagName === 'mfrac') {\n                const numEl = el.children[0];\n                const denEl = el.children[1];\n                const numNode = buildSemanticNavNode({ type: 'single', element: numEl }, node, depth + 1);\n                const denNode = buildSemanticNavNode({ type: 'single', element: denEl }, node, depth + 1);\n                \n                const fracSelfNode = {\n                    parent: node,\n                    depth: depth + 1,\n                    text: node.text,\n                    html: `<span class=\"frac-nav\"><span class=\"num\">${numNode.html}</span> / <span class=\"den\">${denNode.html}</span></span>`,\n                    speech: node.speech,\n                    navSpeech: \"Fraction: \" + node.speech,\n                    mathmlStr: node.mathmlStr,\n                    children: [numNode, denNode],\n                    type: 'mfrac_self',\n                    levelName: \"Fraction\",\n                    domElements: [el]\n                };\n\n                numNode.levelName = \"Numerator\";\n                numNode.navSpeech = \"Numerator: \" + numNode.speech;\n                denNode.levelName = \"Denominator\";\n                denNode.navSpeech = \"Denominator: \" + denNode.speech;\n                \n                node.children.push(fracSelfNode);\n                node.children.push(numNode);\n                node.children.push(denNode);\n                node.html = `<span class=\"frac-nav\"><span class=\"num\">${numNode.html}</span> / <span class=\"den\">${denNode.html}</span></span>`;\n            } else if (tagName === 'msup' || tagName === 'msub') {\n                const baseEl = el.children[0];\n                const subSupEl = el.children[1];\n                const baseNode = buildSemanticNavNode({ type: 'single', element: baseEl }, node, depth + 1);\n                const subSupNode = buildSemanticNavNode({ type: 'single', element: subSupEl }, node, depth + 1);\n                \n                baseNode.navSpeech = baseNode.speech;\n                const supText = subSupEl.textContent.trim();\n                if (tagName === 'msup') {\n                    if (supText === '*' || supText === '\u2217' || supText === 'ast') {\n                        node.speech = baseNode.speech + \" conjugate\";\n                        subSupNode.navSpeech = \"conjugate\";\n                    } else {\n                        subSupNode.navSpeech = \"to the power of \" + subSupNode.speech;\n                    }\n                    node.html = `${baseNode.html}<sup>${subSupNode.html}</sup>`;\n                } else {\n                    subSupNode.navSpeech = \"sub \" + subSupNode.speech;\n                    node.html = `${baseNode.html}<sub>${subSupNode.html}</sub>`;\n                }\n                node.children.push(baseNode);\n                node.children.push(subSupNode);\n            } else if (tagName === 'msubsup') {\n                const baseEl = el.children[0];\n                const subEl = el.children[1];\n                const supEl = el.children[2];\n                const baseNode = buildSemanticNavNode({ type: 'single', element: baseEl }, node, depth + 1);\n                const subNode = buildSemanticNavNode({ type: 'single', element: subEl }, node, depth + 1);\n                const supNode = buildSemanticNavNode({ type: 'single', element: supEl }, node, depth + 1);\n                \n                baseNode.navSpeech = baseNode.speech;\n                subNode.navSpeech = \"sub \" + subNode.speech;\n                supNode.navSpeech = \"raised to \" + supNode.speech;\n                node.html = `${baseNode.html}<sub>${subNode.html}</sub><sup>${supNode.html}</sup>`;\n                node.children.push(baseNode);\n                node.children.push(subNode);\n                node.children.push(supNode);\n            } else if (tagName === 'mtable') {\n                // 2D Grid navigation support for matrices and systems of equations\n                node.levelName = \"Matrix\";\n                node.speech = \"Matrix\";\n                node.html = `<div class=\"matrix-grid\">[Matrix]</div>`;\n                const rows = Array.from(el.children).filter(c => c.tagName.toLowerCase() === 'mtr');\n                rows.forEach((rowEl, rIdx) => {\n                    const rowNode = {\n                        parent: node,\n                        depth: depth + 1,\n                        text: `Row ${rIdx + 1}`,\n                        html: `Row ${rIdx + 1}`,\n                        speech: `Row ${rIdx + 1}`,\n                        navSpeech: `Row ${rIdx + 1}`,\n                        children: [],\n                        type: 'mtr',\n                        levelName: `Row ${rIdx + 1}`,\n                        domElements: [rowEl]\n                    };\n                    const cells = Array.from(rowEl.children).filter(c => c.tagName.toLowerCase() === 'mtd');\n                    cells.forEach((cellEl, cIdx) => {\n                        const cellChild = Array.from(cellEl.children);\n                        const subGroups = groupChildElements(cellChild.length ? cellChild : [cellEl]);\n                        const grouped = semanticGroup(subGroups);\n                        const cellNode = buildSemanticNavNode(grouped, rowNode, depth + 2);\n                        cellNode.levelName = `Row ${rIdx + 1}, Column ${cIdx + 1}`;\n                        cellNode.navSpeech = `Row ${rIdx + 1}, Column ${cIdx + 1}: ${cellNode.speech}`;\n                        rowNode.children.push(cellNode);\n                    });\n                    node.children.push(rowNode);\n                });\n            } else if (tagName === 'msqrt') {\n                const subElList = Array.from(el.children);\n                let targetList = subElList;\n                if (subElList.length === 1 && subElList[0].tagName.toLowerCase() === 'mrow') {\n                    targetList = Array.from(subElList[0].children);\n                }\n                const subGroups = groupChildElements(targetList);\n                const grouped = semanticGroup(subGroups);\n                const innerNode = buildSemanticNavNode(grouped, node, depth + 1);\n\n                const opNode = {\n                    parent: node,\n                    depth: depth + 1,\n                    text: \"\u221a\",\n                    html: \"\u221a\",\n                    speech: \"Square root of\",\n                    navSpeech: \"Square root of\",\n                    mathmlStr: \"<mo>\u221a</mo>\",\n                    children: [],\n                    type: \"mo\",\n                    levelName: \"Square Root Operator\",\n                    domElements: [el]\n                };\n\n                innerNode.levelName = \"Radicand\";\n                innerNode.navSpeech = innerNode.speech;\n                innerNode.parent = node;\n                innerNode.depth = depth + 1;\n\n                node.children.push(opNode);\n                node.children.push(innerNode);\n                node.html = `\u221a(${innerNode.html})`;\n            } else if (tagName === 'mrow' || tagName === 'math') {\n                const subGroups = groupChildElements(Array.from(el.children));\n                const grouped = semanticGroup(subGroups);\n                if (grouped.type === 'single') {\n                    return buildSemanticNavNode(grouped, parent, depth);\n                }\n                return buildSemanticNavNode(grouped, parent, depth);\n            }\n        } else if (semNode.type === 'fence') {\n            const subEls = semNode.elements;\n            node.text = subEls.map(el => el.textContent.trim()).join(\"\");\n            node.type = 'fence';\n            node.mathmlStr = `<mrow>${subEls.map(el => new XMLSerializer().serializeToString(el)).join(\"\")}</mrow>`;\n            const insideEls = subEls.slice(1, -1);\n            const insideSpeech = insideEls.map(el => getElementSpeech(el)).filter(Boolean).join(\" \");\n            node.speech = \"quantity \" + insideSpeech;\n            const subGroups = groupChildElements(insideEls);\n            const grouped = semanticGroup(subGroups);\n            const innerNode = buildSemanticNavNode(grouped, node, depth + 1);\n            node.children.push(innerNode);\n            const openFence = subEls[0].textContent.trim();\n            const closeFence = subEls[subEls.length - 1].textContent.trim();\n            node.html = `${openFence}${innerNode.html}${closeFence}`;\n            node.domElements = subEls;\n        } else {\n            node.type = semNode.type;\n            const rawChildren = semNode.children.map(child => buildSemanticNavNode(child, node, depth + 1));\n            node.children = [];\n            rawChildren.forEach((child, idx) => {\n                if (node.type === 'relation' || child.type !== 'mo') {\n                    child.navSpeech = child.speech;\n                    node.children.push(child);\n                }\n            });\n            node.text = rawChildren.map(c => c.text).join(\" \");\n            node.speech = rawChildren.map(c => c.speech).join(\" \");\n            node.mathmlStr = `<mrow>${rawChildren.map(c => c.mathmlStr || '').join(\"\")}</mrow>`;\n            \n            if (node.type === 'addition' || node.type === 'relation') {\n                node.html = rawChildren.map(c => c.html).join(\" \");\n            } else if (node.type === 'multiplication') {\n                node.html = rawChildren.map(c => c.html).join(\"\");\n                if (node.children.every(c => c.children.length === 0 && (c.type === 'mi' || c.type === 'mn' || c.type === 'mo'))) {\n                    node.children = [];\n                }\n            } else {\n                node.html = rawChildren.map(c => c.html).join(\" \");\n            }\n            \n            let childEls = [];\n            rawChildren.forEach(child => {\n                if (child.domElements) {\n                    childEls = childEls.concat(child.domElements);\n                }\n            });\n            node.domElements = childEls;\n        }\n\n        if (!node.navSpeech) {\n            node.navSpeech = node.speech;\n        }\n\n        if (depth === 0) {\n            node.levelName = \"Level 0: Whole Equation\";\n        } else if (node.type === 'relation') {\n            node.levelName = \"Level 1: Equation Relation\";\n        } else if (node.type === 'addition') {\n            const hasFraction = node.children.some(c => c.type === 'mfrac');\n            if (hasFraction) {\n                node.levelName = \"Level \" + depth + \": Sum of Fractions\";\n            } else {\n                node.levelName = \"Level \" + depth + \": Sum of Terms\";\n            }\n        } else if (node.type === 'multiplication') {\n            node.levelName = \"Level \" + depth + \": Product of Factors\";\n        } else if (node.type === 'mfrac') {\n            node.levelName = \"Level \" + depth + \": Fraction\";\n        } else if (!node.levelName) {\n            node.levelName = \"Level \" + depth + \": Component\";\n        }\n\n        return node;\n    }\n\n\n    function buildNavNode(group, parent = null, depth = 0) {\n        let elements = [];\n        if (group.type === 'single') {\n            const el = group.element;\n            const tagName = el.tagName.toLowerCase();\n            if (tagName === 'mrow' || tagName === 'math') {\n                elements = Array.from(el.children);\n            } else {\n                elements = [el];\n            }\n        } else if (group.type === 'fence') {\n            elements = group.elements;\n        } else {\n            elements = group.elements || [];\n        }\n\n        const fencedGroups = groupChildElements(elements);\n        const semNode = semanticGroup(fencedGroups);\n        return buildSemanticNavNode(semNode, parent, depth);\n    }\n\n    function getElementSpeech(el) {\n        const tag = el.tagName.toLowerCase();\n        const text = el.textContent.trim();\n        if (tag === 'mi' || tag === 'mn') {\n            return text;\n        } else if (tag === 'mo') {\n            const ops = {\n                '+': 'plus',\n                '-': 'minus',\n                '\u2212': 'minus',\n                '*': 'times',\n                '\u00b7': 'times',\n                '\u22c5': 'times',\n                '\u00d7': 'times',\n                '/': 'divided by',\n                '\u00f7': 'divided by',\n                '=': 'equals',\n                '\u2260': 'does not equal',\n                '<': 'is less than',\n                '>': 'is greater than',\n                '\u2264': 'is less than or equal to',\n                '\u2265': 'is greater than or equal to',\n                '\u2248': 'is approximately equal to',\n                '\u2261': 'is equivalent to',\n                '\u221d': 'is proportional to',\n                '\u2208': 'is an element of',\n                '\u2209': 'is not an element of',\n                '\u2282': 'is a proper subset of',\n                '\u2286': 'is a subset of',\n                '\u21d2': 'implies',\n                '\u21d4': 'if and only if',\n                '\u00b1': 'plus or minus',\n                '\u2213': 'minus or plus',\n                '\u2295': 'direct sum',\n                '\u2297': 'tensor product',\n                '\u2229': 'intersection',\n                '\u222a': 'union',\n                '\u2211': 'summation',\n                '\u220f': 'product',\n                '\u222b': 'integral',\n                '\u2202': 'partial derivative',\n                '\u2207': 'del',\n                '(': 'open parenthesis',\n                ')': 'close parenthesis',\n                '[': 'open bracket',\n                ']': 'close bracket',\n                '{': 'open brace',\n                '}': 'close brace'\n            };\n            return ops[text] || text;\n        }\n        return text;\n    }\n});";
